import CoreLocation

struct Park: Identifiable, Hashable {
    let id = UUID()
    let name: String
    let coordinate: CLLocationCoordinate2D
    
    // Conformance to Hashable for SwiftUI Picker
    static func == (lhs: Park, rhs: Park) -> Bool {
        lhs.id == rhs.id
    }
    
    func hash(into hasher: inout Hasher) {
        hasher.combine(id)
    }
}

